python3 -c "
from collections import deque
from itertools import islice

def consume(iterator, n=None):
    if n is None:
        list(iterator)
    else:
        next(islice(iterator, n, n), None)

class seekable_test:
    def __init__(self, iterable, maxlen=None):
        self._source = iter(iterable)
        if maxlen is None:
            self._cache = []
        else:
            self._cache = deque([], maxlen)
        self._index = None

    def __iter__(self):
        return self

    def __next__(self):
        print(f'  __next__: _index={self._index}, cache_len={len(self._cache)}')
        if self._index is not None:
            try:
                item = self._cache[self._index]
            except IndexError:
                print(f'    IndexError, resetting _index')
                self._index = None
            else:
                self._index += 1
                return item

        item = next(self._source)
        self._cache.append(item)
        return item

    def seek(self, index):
        print(f'seek({index})')
        self._index = index
        remainder = index - len(self._cache)
        print(f'  remainder={remainder}')
        if remainder > 0:
            consume(self, remainder)

it = seekable_test((str(n) for n in range(20)))
print('=== First 3 items ===')
for i in range(3):
    print(f'Result: {next(it)}')

print('\\n=== Seek to 4 ===')
it.seek(4)
print(f'After seek: _index={it._index}, cache={it._cache}')
print('Next:')
print(f'Result: {next(it)}')
